#!/usr/bin/env python3
import json
import os
import re
import shutil
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE_PATH = '/root/training_feedback_template.hwpx'
JSON_PATH = '/root/training_feedback.json'
OUTPUT_PATH = '/root/training_feedback_ready.hwpx'

PLACEHOLDER_RE = re.compile(r'\{\{\s*([^{}]+?)\s*\}\}')


def _extract_namespaces(raw_xml: bytes) -> dict:
    """Return prefix->uri mapping found in xmlns declarations."""
    # Matches: xmlns="..." or xmlns:hp="..."
    ns = {}
    for m in re.finditer(rb'\sxmlns(?::([A-Za-z_][\w\.-]*))?="([^"]+)"', raw_xml):
        prefix = m.group(1).decode('utf-8') if m.group(1) else ''
        uri = m.group(2).decode('utf-8')
        ns[prefix] = uri
    return ns


def _register_namespaces(nsmap: dict) -> None:
    # Register default namespace (prefix='') too, if present
    for prefix, uri in nsmap.items():
        try:
            ET.register_namespace(prefix, uri)
        except Exception:
            # ElementTree may raise if prefix is invalid; ignore and continue.
            pass


def _digits_only(val) -> str:
    s = str(val)
    digits = re.findall(r'\d+', s)
    return ''.join(digits)


def _format_satisfaction(val) -> str:
    s = str(val)
    m = re.search(r'(\d+(?:\.\d+)?)', s)
    if not m:
        score = 0.0
    else:
        score = float(m.group(1))
    return f"{score:.1f}점 (5.0점 만점)"


def _append_overall_opinion(val) -> str:
    base = str(val)
    suffix = '후속 심화반 검토 요망.'
    if base.endswith((' ', '\t', '\n', '\r')):
        return base + suffix
    return base + ' ' + suffix


def _replacement_for_key(key: str, data: dict) -> str:
    k = key.strip()

    # Direct match
    if k in data:
        v = data[k]
    else:
        # Fallback: try without internal spaces (covers cases like "종합 의견")
        k2 = k.replace(' ', '')
        if k2 in data:
            v = data[k2]
            k = k2
        else:
            # Replace unknown placeholders with empty string so no {{ }} remain.
            print(f"WARN: No JSON value for placeholder '{key}'")
            return ''

    if k in ('참석자수',):
        return _digits_only(v)
    if k in ('만족도',):
        return _format_satisfaction(v)
    if k in ('종합의견', '종합 의견'):
        return _append_overall_opinion(v)

    return str(v)


def _has_placeholder(text: str) -> bool:
    return bool(PLACEHOLDER_RE.search(text or ''))


def _process_section_xml(raw_xml: bytes, data: dict) -> tuple[bytes, bool]:
    """Return (modified_xml_bytes, modified_any) for one XML file."""
    nsmap = _extract_namespaces(raw_xml)
    _register_namespaces(nsmap)

    try:
        root = ET.fromstring(raw_xml)
    except ET.ParseError:
        # If it isn't parseable XML, fall back to plain text substitution.
        try:
            txt = raw_xml.decode('utf-8')
        except UnicodeDecodeError:
            txt = raw_xml.decode('utf-8', errors='replace')

        def repl(m):
            return _replacement_for_key(m.group(1), data)

        new_txt = PLACEHOLDER_RE.sub(repl, txt)
        return new_txt.encode('utf-8'), (new_txt != txt)

    hp_uri = nsmap.get('hp')
    if not hp_uri:
        # Derive from root tag if possible: {uri}local
        if root.tag.startswith('{') and '}' in root.tag:
            hp_uri = root.tag[1:root.tag.index('}')]

    def q(local: str) -> str:
        if not hp_uri:
            return local
        return f'{{{hp_uri}}}{local}'

    modified_any = False

    for p in root.findall('.//' + q('p')):
        ts = p.findall('.//' + q('t'))
        if not ts:
            continue

        concat = ''.join((t.text or '') for t in ts)
        p_modified = False

        # Merge fragmented runs when placeholders exist in the paragraph.
        if _has_placeholder(concat):
            # Move all concatenated text into the first <hp:t>
            if (ts[0].text or '') != concat:
                ts[0].text = concat
                p_modified = True
            # Clear remaining text nodes (preserve structure)
            for t in ts[1:]:
                if t.text:
                    t.text = ''
                    p_modified = True

            def repl(m):
                return _replacement_for_key(m.group(1), data)

            replaced = PLACEHOLDER_RE.sub(repl, concat)
            if replaced != concat:
                ts[0].text = replaced
                p_modified = True

        if p_modified:
            # Remove layout cache (<hp:linesegarray>) to avoid stale rendering.
            for child in list(p):
                if child.tag == q('linesegarray'):
                    p.remove(child)
                    modified_any = True
            modified_any = True

    out_xml = ET.tostring(root, encoding='UTF-8', xml_declaration=True)
    return out_xml, modified_any


def main() -> int:
    if not os.path.exists(TEMPLATE_PATH):
        raise FileNotFoundError(TEMPLATE_PATH)
    if not os.path.exists(JSON_PATH):
        raise FileNotFoundError(JSON_PATH)

    with open(JSON_PATH, 'r', encoding='utf-8') as f:
        data = json.load(f)

    # Per instructions: copy template to output path first.
    shutil.copyfile(TEMPLATE_PATH, OUTPUT_PATH)

    # Now write a fresh zip at OUTPUT_PATH with modified entries.
    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        with zipfile.ZipFile(OUTPUT_PATH, 'w') as zout:
            for info in zin.infolist():
                raw = zin.read(info.filename)
                if info.filename.endswith(('.xml', '.hpf')):
                    new_raw, _modified = _process_section_xml(raw, data)
                    zout.writestr(info, new_raw)
                else:
                    zout.writestr(info, raw)

    print(f"Wrote: {OUTPUT_PATH}")
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

